// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum ScanProgress {
    
    case walking(found: UInt64
    )
    case hashing(done: UInt64, total: UInt64
    )
    case analyzing(done: UInt64, total: UInt64
    )
    case embedding(done: UInt64, total: UInt64
    )
}


#if compiler(>=6)
extension ScanProgress: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeScanProgress: FfiConverterRustBuffer {
    typealias SwiftType = ScanProgress

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ScanProgress {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .walking(found: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .hashing(done: try FfiConverterUInt64.read(from: &buf), total: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 3: return .analyzing(done: try FfiConverterUInt64.read(from: &buf), total: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .embedding(done: try FfiConverterUInt64.read(from: &buf), total: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ScanProgress, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .walking(found):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(found, into: &buf)
            
        
        case let .hashing(done,total):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(done, into: &buf)
            FfiConverterUInt64.write(total, into: &buf)
            
        
        case let .analyzing(done,total):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(done, into: &buf)
            FfiConverterUInt64.write(total, into: &buf)
            
        
        case let .embedding(done,total):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(done, into: &buf)
            FfiConverterUInt64.write(total, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeScanProgress_lift(_ buf: RustBuffer) throws -> ScanProgress {
    return try FfiConverterTypeScanProgress.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeScanProgress_lower(_ value: ScanProgress) -> RustBuffer {
    return FfiConverterTypeScanProgress.lower(value)
}


